package org.dromara.ai.workspace;
import lombok.RequiredArgsConstructor;
import org.dromara.common.json.utils.JsonUtils;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;
@Service
@RequiredArgsConstructor
public class WorkspacePublication {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final AiResourceGuard guard;private final WorkspacePermissions permissions;private final WorkspaceConversations conversations;
 private Map<String,Object> owned(UUID id,long user){var row=guard.require(id,user,AiResourceGuard.Action.PUBLISH);if(!guard.owner(row,user))throw new WorkspaceDenied(403,"OwnerPublicationRequired");return row;}
 public Map<String,Object> publicationCheck(UUID id,int version,long user){
  var row=owned(id,user);
  if(((Number)row.get("latest_version")).intValue()!=version)throw new WorkspaceDenied(409,"VersionConflict");
  var issues=dependencyIssues(id,version,row.get("resource_type").toString());
  return Map.of("ready",issues.isEmpty(),"issues",issues);
 }
 private List<Map<String,String>> dependencyIssues(UUID id,int version,String type){
  if(!"ASSISTANT".equals(type))return List.of();
  var versions=jdbc.queryForList("SELECT config::text FROM ai_resource_version WHERE resource_id=? AND version=?",id,version);
  if(versions.size()!=1)throw new WorkspaceDenied(404,"VersionNotFound");
  var config=JsonUtils.parseMap(versions.getFirst().get("config").toString());
  List<Map<String,String>> issues=new ArrayList<>();
  UUID model=UUID.fromString(config.get("modelId").toString());
  boolean modelReady=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_model m JOIN ai_provider p ON p.id=m.provider_id WHERE m.id=? AND m.enabled AND m.streaming AND p.enabled)",Boolean.class,model));
  if(!modelReady)issues.add(Map.of("type","MODEL","id",model.toString(),"code","ModelUnavailable"));
  for(String resourceType:List.of("SKILL","MCP","KNOWLEDGE","TOOL")){
   String key=resourceType.toLowerCase(Locale.ROOT)+"Ids";
   for(Object raw:(List<?>)config.getOrDefault(key,List.of())){
    UUID dependency=UUID.fromString(raw.toString());
    boolean active=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_resource WHERE id=? AND resource_type=? AND enabled AND NOT security_disabled AND lifecycle_state='ACTIVE' AND published_version IS NOT NULL)",Boolean.class,dependency,resourceType));
    if(!active)issues.add(Map.of("type",resourceType,"id",dependency.toString(),"code","ResourceUnavailable"));
    if(active&&"MCP".equals(resourceType)){
     boolean connected=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_mcp_connection c JOIN ai_resource r ON r.id=c.resource_id WHERE c.resource_id=? AND c.enabled AND c.status='READY' AND c.template_version=r.published_version)",Boolean.class,dependency));
     if(!connected)issues.add(Map.of("type","MCP","id",dependency.toString(),"code","McpConnectionNotReady"));
    }
   }
  }
  return issues;
 }
 private void audit(long user,String action,UUID id,Map<String,Object> data){jdbc.update("INSERT INTO ai_security_event(id,actor_user_id,action,resource_id,metadata) VALUES(?,?,?,?,?::jsonb)",UUID.randomUUID(),user,action,id,JsonUtils.toJsonString(data));}
 public Map<String,Object> submit(UUID id,int version,long user){return tx.execute(status->{jdbc.queryForList("SELECT id FROM ai_resource WHERE id=? FOR UPDATE",id);var r=owned(id,user);if(!"ACTIVE".equals(r.get("lifecycle_state"))||!Boolean.TRUE.equals(r.get("enabled"))||Boolean.TRUE.equals(r.get("security_disabled")))throw new WorkspaceDenied(409,"ResourceUnavailable");if(((Number)r.get("latest_version")).intValue()!=version)throw new WorkspaceDenied(409,"VersionConflict");if(!dependencyIssues(id,version,r.get("resource_type").toString()).isEmpty())throw new WorkspaceDenied(409,"AssistantDependencyUnavailable");var pending=jdbc.queryForList("SELECT id,version FROM ai_resource_review WHERE resource_id=? AND state='PENDING'",id);if(!pending.isEmpty()){if(((Number)pending.getFirst().get("version")).intValue()!=version)throw new WorkspaceDenied(409,"ReviewAlreadyPending");return Map.of("id",pending.getFirst().get("id").toString(),"state","PENDING");}UUID review=UUID.randomUUID();jdbc.update("INSERT INTO ai_resource_review(id,resource_id,version,requested_by) VALUES(?,?,?,?)",review,id,version,user);if("KNOWLEDGE".equals(r.get("resource_type"))){int count=jdbc.update("INSERT INTO ai_review_document(review_id,document_id,version) SELECT ?,id,indexed_version FROM ai_knowledge_document WHERE base_id=? AND deleted_at IS NULL AND indexed_version IS NOT NULL",review,id);if(count==0)throw new WorkspaceDenied(409,"KnowledgeIndexNotReady");}jdbc.update("UPDATE ai_resource_version SET review_state='PENDING' WHERE resource_id=? AND version=?",id,version);audit(user,"resource.publication.requested",id,Map.of("reviewId",review.toString(),"version",version));return Map.of("id",review.toString(),"state","PENDING");});}
 public List<Map<String,Object>> ownReviews(UUID id,long user){owned(id,user);return jdbc.queryForList("SELECT id::text,version,state,reason,created_at::text,reviewed_at::text FROM ai_resource_review WHERE resource_id=? ORDER BY created_at DESC LIMIT 30",id);}
 public List<Map<String,Object>> reviews(long user,int page){permissions.require(user,"ai:resource:review");return jdbc.queryForList("SELECT x.id::text,x.resource_id::text,x.version,x.state,x.requested_by::text,x.reason,x.created_at::text,r.resource_type,r.owner_type,v.metadata->>'name' AS name FROM ai_resource_review x JOIN ai_resource r ON r.id=x.resource_id JOIN ai_resource_version v ON v.resource_id=x.resource_id AND v.version=x.version ORDER BY x.created_at DESC LIMIT 30 OFFSET ?",(Math.max(1,Math.min(page,1000))-1)*30);}
 public Map<String,Object> review(UUID id,long user){permissions.require(user,"ai:resource:review");var rows=jdbc.queryForList("SELECT x.id::text,x.resource_id::text,x.version,x.state,x.requested_by::text,x.reason,r.resource_type,v.config::text,v.metadata::text FROM ai_resource_review x JOIN ai_resource r ON r.id=x.resource_id JOIN ai_resource_version v ON v.resource_id=x.resource_id AND v.version=x.version WHERE x.id=?",id);if(rows.isEmpty()||"WithdrawnByOwner".equals(rows.getFirst().get("reason")))throw new WorkspaceDenied(404,"ReviewNotFound");var result=new LinkedHashMap<>(rows.getFirst());result.put("config",JsonUtils.parseMap(result.get("config").toString()));result.put("metadata",JsonUtils.parseMap(result.get("metadata").toString()));result.put("documents",jdbc.queryForList("SELECT d.document_id::text,d.version,f.filename,v.content_hash FROM ai_review_document d JOIN ai_knowledge_document_version v ON v.document_id=d.document_id AND v.version=d.version JOIN ai_file f ON f.id=v.file_id WHERE review_id=? ORDER BY d.document_id LIMIT 50",id));audit(user,"resource.review.snapshot.viewed",UUID.fromString(result.get("resource_id").toString()),Map.of("reviewId",id.toString()));return result;}
 public Map<String,Object> reviewDocument(UUID review,UUID document,long user){permissions.require(user,"ai:resource:review");if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_resource_review WHERE id=? AND reason IS DISTINCT FROM 'WithdrawnByOwner')",Boolean.class,review)))throw new WorkspaceDenied(404,"ReviewNotFound");var rows=jdbc.queryForList("SELECT d.document_id::text,d.version,f.filename,v.text_content AS content FROM ai_review_document d JOIN ai_knowledge_document_version v ON v.document_id=d.document_id AND v.version=d.version JOIN ai_file f ON f.id=v.file_id WHERE d.review_id=? AND d.document_id=?",review,document);if(rows.isEmpty())throw new WorkspaceDenied(404,"ReviewDocumentNotFound");audit(user,"resource.review.document.viewed",null,Map.of("reviewId",review.toString(),"documentId",document.toString()));return rows.getFirst();}
 public void decide(UUID review,long user,boolean approve,String reason){permissions.require(user,"ai:resource:review");if(reason==null||reason.isBlank()||reason.length()>1000)throw new WorkspaceDenied(400,"ReviewReasonRequired");tx.executeWithoutResult(status->{var first=jdbc.queryForList("SELECT resource_id FROM ai_resource_review WHERE id=?",review);if(first.isEmpty())throw new WorkspaceDenied(404,"ReviewNotFound");UUID id=(UUID)first.getFirst().get("resource_id");jdbc.queryForList("SELECT id FROM ai_resource WHERE id=? FOR UPDATE",id);var x=jdbc.queryForList("SELECT * FROM ai_resource_review WHERE id=? FOR UPDATE",review).getFirst();if(!"PENDING".equals(x.get("state")))throw new WorkspaceDenied(409,"ReviewAlreadyDecided");var r=jdbc.queryForList("SELECT * FROM ai_resource WHERE id=?",id).getFirst();if("USER".equals(r.get("owner_type"))&&Objects.toString(r.get("owner_user_id")).equals(Long.toString(user)))throw new WorkspaceDenied(403,"IndependentReviewerRequired");if(approve){if("ARCHIVED".equals(r.get("lifecycle_state"))||Boolean.TRUE.equals(r.get("security_disabled"))||!Boolean.TRUE.equals(r.get("enabled")))throw new WorkspaceDenied(409,"ResourceUnavailable");if(!Objects.equals(r.get("latest_version"),x.get("version")))throw new WorkspaceDenied(409,"ReviewVersionSuperseded");if(!dependencyIssues(id,((Number)x.get("version")).intValue(),r.get("resource_type").toString()).isEmpty())throw new WorkspaceDenied(409,"AssistantDependencyUnavailable");if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_review_document rd JOIN ai_knowledge_document d ON d.id=rd.document_id WHERE rd.review_id=? AND d.deleted_at IS NOT NULL)",Boolean.class,review)))throw new WorkspaceDenied(409,"ReviewDocumentDeleted");jdbc.update("UPDATE ai_resource SET visibility='ENTERPRISE_PUBLIC',published_version=?,lifecycle_state='ACTIVE',updated_by=?,updated_at=NOW() WHERE id=?",x.get("version"),user,id);jdbc.update("DELETE FROM ai_public_document WHERE resource_id=?",id);jdbc.update("INSERT INTO ai_public_document(resource_id,document_id,version) SELECT ?,document_id,version FROM ai_review_document WHERE review_id=?",id,review);}String state=approve?"APPROVED":"REJECTED";jdbc.update("UPDATE ai_resource_review SET state=?,reviewed_by=?,reason=?,reviewed_at=NOW() WHERE id=?",state,user,reason,review);jdbc.update("UPDATE ai_resource_version SET review_state=? WHERE resource_id=? AND version=?",state,id,x.get("version"));audit(user,approve?"resource.publication.approved":"resource.publication.rejected",id,Map.of("reviewId",review.toString(),"version",x.get("version"),"reason",reason));});}
 public void unpublish(UUID id,long user){tx.executeWithoutResult(status->{jdbc.queryForList("SELECT id FROM ai_resource WHERE id=? FOR UPDATE",id);owned(id,user);jdbc.update("UPDATE ai_resource_version SET review_state='REJECTED' WHERE resource_id=? AND review_state='PENDING'",id);jdbc.update("UPDATE ai_resource_review SET state='REJECTED',reason='WithdrawnByOwner',reviewed_by=?,reviewed_at=NOW() WHERE resource_id=? AND state='PENDING'",user,id);jdbc.update("UPDATE ai_resource SET visibility=CASE WHEN EXISTS(SELECT 1 FROM ai_resource_share WHERE resource_id=? AND status='ACTIVE') THEN 'SHARED' ELSE 'PRIVATE' END,auth_version=auth_version+1,updated_at=NOW(),updated_by=? WHERE id=?",id,user,id);jdbc.update("DELETE FROM ai_public_document WHERE resource_id=?",id);audit(user,"resource.unpublished",id,Map.of());});conversations.revokeResource(id);}
 public List<Map<String,Object>> shares(UUID id,long user){var r=guard.require(id,user,AiResourceGuard.Action.SHARE);if(!guard.owner(r,user))throw new WorkspaceDenied(403,"OwnerSharingRequired");return jdbc.queryForList("SELECT s.id::text,s.subject_type,s.subject_id::text,to_json(s.actions)::text AS actions,s.status,CASE s.subject_type WHEN 'USER' THEN (SELECT nick_name FROM sys_user WHERE user_id=s.subject_id) WHEN 'ROLE' THEN (SELECT role_name FROM sys_role WHERE role_id=s.subject_id) ELSE (SELECT dept_name FROM sys_dept WHERE dept_id=s.subject_id) END AS name FROM ai_resource_share s WHERE s.resource_id=? ORDER BY s.created_at DESC LIMIT 100",id);}
 public List<Map<String,Object>> targets(String type,String query,long user){permissions.require(user,"ai:resource:share");if(query==null||query.length()<2||query.length()>80)throw new WorkspaceDenied(400,"ShareSearchTooShort");String table,column,name;switch(type){case "USER"->{table="sys_user";column="user_id";name="nick_name";}case "ROLE"->{table="sys_role";column="role_id";name="role_name";}case "DEPARTMENT"->{table="sys_dept";column="dept_id";name="dept_name";}default->throw new WorkspaceDenied(400,"InvalidShareSubject");}String pattern="%"+query.replace("!","!!").replace("%","!%").replace("_","!_")+"%";if("USER".equals(type))return jdbc.queryForList("SELECT user_id::text AS id,nick_name AS name FROM sys_user WHERE status='0' AND del_flag='0' AND (nick_name ILIKE ? ESCAPE '!' OR user_name ILIKE ? ESCAPE '!') ORDER BY user_id LIMIT 20",pattern,pattern);return jdbc.queryForList("SELECT "+column+"::text AS id,"+name+" AS name FROM "+table+" WHERE status='0' AND del_flag='0' AND "+name+" ILIKE ? ESCAPE '!' ORDER BY "+column+" LIMIT 20",pattern);}
}
